/**
 * The simple locations (model locations@1): the heading, a description, the offices as a list (the name, the
 * address) and one picture (a map or a place). Axes: media (start: the picture before the copy from md up, end:
 * after it).
 */
import { type ReactNode } from "react";
import { Block, Box, Container, List, ListItem, Stack, Text, Title } from "../compose";
import { MediaFrame } from "../components/media-frame";
import { cn } from "../utils";
import type { LocationItem } from "./locations-simple.types";

export type LocationsSimpleProps = {
  id: string;
  title: string;
  description?: string;
  image?: string;
  imageAlt: string;
  items: LocationItem[];
  level?: 1 | 2 | 3;
  padding?: "compact" | "standard" | "spacious";
  align?: "start" | "center" | "end";
  media?: "start" | "end";
  landmarkLabel?: string;
};

export function LocationsSimple({
  id,
  title,
  description = "",
  image = "",
  imageAlt,
  items,
  level = 2,
  padding = "standard",
  align = "start",
  media = "start",
  landmarkLabel,
}: LocationsSimpleProps) {
  const titleId = id + "-title";
  const column =
    (align as string) === "center" ? "center"
    : (align as string) === "end" ? "end"
    : "start";
  const textAlign =
    (align as string) === "center" ? "text-center"
    : (align as string) === "end" ? "text-end"
    : "text-start";
  const itemsAlign =
    (align as string) === "center" ? "items-center"
    : (align as string) === "end" ? "items-end"
    : "items-start";
  const selfAlign =
    (align as string) === "center" ? "self-center"
    : (align as string) === "end" ? "self-end"
    : "";
  const pictureClass = ((media as string) === "start") ? "md:order-first" : "";
  return (
    <Block
      tag="section"
      className={
        (padding as string) === "compact" ? "py-8 lg:py-16"
        : (padding as string) === "spacious" ? "py-24 lg:py-40"
        : "py-16 lg:py-32"
      }
      aria-labelledby={(landmarkLabel ? undefined : titleId)}
      aria-label={landmarkLabel}
      data-slot="locations-simple"
    >
      <Container className="mx-auto w-full max-w-6xl px-4">
        <Box className="grid grid-cols-1 items-center gap-12 md:grid-cols-2">
          <Stack gap="8" align="stretch">
            <Stack gap="4" align={column} className={cn("max-w-2xl", selfAlign)}>
              <Title as={level} size="3xl" weight="bold" className={cn("tracking-tight", textAlign)} id={titleId}>
                {title}
              </Title>
              {description ? (
                <Text size="base" className={cn("text-muted-foreground", textAlign)}>
                  {description}
                </Text>
              ) : null}
            </Stack>
            <List tag="ul" className={cn("m-0 w-full list-none p-0", "grid grid-cols-1 gap-6 sm:grid-cols-2")}>
              {(items ?? []).map((l) => (
                <ListItem key={l.id} className={cn("flex flex-col gap-2", itemsAlign)} data-slot="location">
                  <Title as={(level + 1)} size="base" weight="semibold" className={textAlign}>
                    {l.title}
                  </Title>
                  {l.description ? (
                    <Text size="sm" className={cn("text-muted-foreground", textAlign)}>
                      {l.description}
                    </Text>
                  ) : null}
                </ListItem>
              ))}
            </List>
          </Stack>
          <MediaFrame alt={imageAlt} src={image} ratio="1/1" className={pictureClass} />
        </Box>
      </Container>
    </Block>
  );
}

